INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '拓展', 2, '{"stem": "将竖式 638×7=4466 中圈出的部分与右边的乘法算式连一连：638×7 圈出的三步分别是 7×600、7×30、7×8，它们分别对应竖式中的哪一位？", "options": null}', '7×600 对应百位（写6 进位 4）；7×30 对应十位（写21，但末位2 进位2 → 整体写21）；7×8 对应个位（写56，进位 5）。638×7=4466 完整竖式：个位 7×8=56 写6 进5；十位 7×30+5=215 写5 进21；百位 7×600+21=4221 → 修正 638×7=4466（实际正确竖式：8×7=56 写6进5；3×7+5=26 写6进2；6×7+2=44 → 4466）', '638×7 竖式展开：个位 7×8=56（写6 进5），十位 7×3+5=26（写6 进2），百位 7×6+2=44 → 4466。三步对应 7×8、7×30、7×600。', 'paper', '["practice", "ykl3sx", "2.7"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '计算', 2, '{"stem": "先说一说积是几位数，再用竖式计算：418×6=", "options": null}', '四位数；2508', '418×6：6×8=48，6×10=60，6×400=2400 → 48+60+2400=2508；积是四位数。', 'paper', '["practice", "ykl3sx", "2.7"]', NULL, 0);

