INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '填空', 3, '{"stem": "水果店运来 46 筐石榴，每筐 5 千克，用竖式计算 46×5。竖式中箭头所指的这一步的结果表示（ ）筐石榴的质量。", "options": null}', '40筐', '46×5 竖式：5×6=30（个位），5×40=200（十位）。箭头指 200 = 40×5，表示 40 筐石榴的质量。', 'paper', '["practice", "ykl3sx", "2.7"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '应用题', 3, '{"stem": "彩虹小学同学们每人准备一面国庆小红旗。平均每个年级有243名学生，共五个年级，准备1200面小红旗够吗？如果够还剩多少？如果不够还缺多少？", "options": null}', '不够；还缺15面', '总需求：243×5=1215（面）；1215−1200=15（面）<0，不够，缺 15 面。', 'paper', '["practice", "ykl3sx", "2.7"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '拓展', 3, '{"stem": "在括号里填出 □、A、O 表示的数：□A〇4 × 3 = 5□A〇（□、A、O 各表示什么数字？）", "options": null}', '□=1，A=7，O=2；1724×3=5172', '从个位倒推：4×3=12 → 积个位〇=2，进 1；十位：3×〇+1=A → 3×2+1=7 → A=7（不进位）；百位：3×A=21 → 写 1（积百位 □=1）进 2；千位：3×□+2=5 → 1×3+2=5 ✓。验算 1724×3=5172 ✓ → □=1, A=7, O=2。', 'paper', '["practice", "ykl3sx", "2.7"]', NULL, 0);
